test('issueInvoice handles different years correctly', () => {
  const r2025 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-31',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2026 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const existing = ['INV-2025-0005'];
  const result2025 = issueInvoice(r2025.value, existing);
  const result2026 = issueInvoice(r2026.value, existing);
  assert.equal(result2025.value.number, 'INV-2025-0006');
  assert.equal(result2026.value.number, 'INV-2026-0001');
});

